/*
 * A086713  A squarefree sequence: define a mapping from the set of strings
 *          over the alphabet {0,1,2} by f(0)=01201, f(1)=020121, f(2)=0212021
 *          and f of the concatenation of s and t is the concatenation of f(s)
 *          and f(t). Then each of 0, f(0), f(f(0)), ... is an initial
 *          substring of the next; their limit is th...
 * https://oeis.org/A086713
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  easy, nonn
 * Formula:   sequence A086713 – the infinite word generated by the morphism
 *            f(0)=01201, f(1)=020121, f(2)=0212021, with the fixed point
 *            starting from 0. a(n) is the nth symbol of that word
 * Range:     u8 n <= 104, u16 n <= 104, u32 n <= 104, u64 n <= 104,
 *            u128 n <= 104, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>

/* Public entry point with external linkage. */
seq_t a(idx_t n)
{
    static char *word = NULL;
    static size_t len   = 0;

    /* initialise with the seed symbol '0' */
    if (!word) {
        word = (char*)malloc(1);
        word[0] = '0';
        len = 1;
    }

    /* grow the word until it contains the requested position n */
    while (len <= (size_t)n) {
        /* first compute the length of the next expansion */
        size_t newlen = 0;
        for (size_t i = 0; i < len; ++i) {
            switch (word[i]) {
                case '0': newlen += 5; break;  /* 01201 */
                case '1': newlen += 6; break;  /* 020121 */
                default : newlen += 7; break;  /* 0212021  (word[i]=='2') */
            }
        }

        /* allocate the new word */
        char *next = (char*)malloc(newlen);
        size_t pos = 0;
        for (size_t i = 0; i < len; ++i) {
            const char *map;
            size_t mlen;
            switch (word[i]) {
                case '0': map = "01201";   mlen = 5; break;
                case '1': map = "020121";  mlen = 6; break;
                default : map = "0212021"; mlen = 7; break; /* '2' */
            }
            memcpy(next + pos, map, mlen);
            pos += mlen;
        }

        /* keep the new word for future calls */
        free(word);
        word = next;
        len = newlen;
    }

    /* return the digit at index n, converted to seq_t */
    return (seq_t)(word[n] - '0');
}
